import{_ as a,a as t,c as o,ac as s}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 18 Porpoises","description":"学习 感官动词的主动与被动转换，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 18 Porpoises","description":"学习 感官动词的主动与被动转换，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 感官动词的主动与被动转换，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 17 A man-made disease","link":"/life/english/new-concept/book-4/unit-03/lesson-017"},"next":{"text":"第四册：流利英语 · Lesson 19 The stuff of dreams","link":"/life/english/new-concept/book-4/unit-03/lesson-019"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 17 A man-made disease","link":"/life/english/new-concept/book-4/unit-03/lesson-017"},"next":{"text":"第四册：流利英语 · Lesson 19 The stuff of dreams","link":"/life/english/new-concept/book-4/unit-03/lesson-019"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-03/lesson-018.md","filePath":"life/english/new-concept/book-4/unit-03/lesson-018.md"}'),n={name:"life/english/new-concept/book-4/unit-03/lesson-018.md"};function i(r,e,l,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="第四册-流利英语-·-lesson-18-porpoises" tabindex="-1">第四册：流利英语 · Lesson 18 Porpoises <a class="header-anchor" href="#第四册-流利英语-·-lesson-18-porpoises" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 18 Porpoises&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕海洋哺乳动物行为阅读科学叙述，注意观察行为与解释意图之间的距离。标题中的 porpoise 与 dolphin 不是可以无条件互换的同一个分类名称；伴读重点在描述动物协作时明确对象与证据。练习使用被动报告结构，保留“研究者观察到”的信息来源。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>porpoise</td><td>/ˈpɔːpəs/</td><td>n.</td><td>鼠海豚</td><td>a harbour porpoise</td></tr><tr><td>mammal</td><td>/ˈmæməl/</td><td>n.</td><td>哺乳动物</td><td>a marine mammal</td></tr><tr><td>surface</td><td>/ˈsɜːfɪs/</td><td>v.</td><td>浮出水面</td><td>surface for air</td></tr><tr><td>behaviour</td><td>/bɪˈheɪvjə/</td><td>n.</td><td>行为</td><td>observe behaviour</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>come to the surface — 浮到水面</li><li>on the basis of — 根据某项证据</li></ul><h2 id="语法讲解-感官动词的主动与被动转换" tabindex="-1">语法讲解：感官动词的主动与被动转换 <a class="header-anchor" href="#语法讲解-感官动词的主动与被动转换" aria-label="Permalink to &quot;语法讲解：感官动词的主动与被动转换&quot;">​</a></h2><p>see/watch/observe + 宾语 + 动词原形强调观察到一个完整动作，接现在分词强调动作正在进行。主动句中的不带 to 不定式在常见被动结构中恢复 to，例如 They saw it surface → It was seen to surface。若原来是 surfacing，被动仍可用 was seen surfacing。观察到动作不等于知道动物的目的，因此 should 或 wanted 等意图表达需要额外证据。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The animal was seen to surface beside the boat twice.</p></blockquote><p>有人看到那只动物在船边浮出水面两次。</p><p>was seen to surface 是感官动词被动结构；twice 表完整动作出现两次，没有说明动作意图。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>The animal was seen surface 缺少 to；主动 We saw it surface 才使用不带 to 结构。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对比朗读 saw it surface 与 was seen to surface，留意被动句中 to 的弱读；把 twice 与地点分开重读。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>A small animal was seen to surface near the harbour. We could not identify its species from that distance. Next time, we will record its shape and movement more carefully.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句海边观察笔记：一次所见、一个未知问题、一次进一步观察计划。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>描述行为而不编造意图，并把物种识别的不确定性写出来。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>把 We saw the animal turn. 改成被动句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The animal was seen to turn.</p><p><strong>解析：</strong> 被动结构中的不定式恢复 to。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>示例是否说明动物想帮助船上的人？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> 它只报告位置与次数。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>填空：We watched the animal ___ slowly.（swimming / to swim）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> swimming</p><p><strong>解析：</strong> watch + 宾语 + 分词描述正在进行的动作。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：感官动词的主动与被动转换。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-017">上一课</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-03/lesson-019">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=a(n,[["render",i]]);export{u as __pageData,m as default};
